// AUTO-GENERATED by scripts/fetch-products.mjs at build time. Do not edit by hand.
// Placeholder committed on purpose — overwritten with real Firestore data
// whenever the prebuild script runs with credentials available. CI has no
// Firestore service account, so it always falls back to this file as-is.
// Helper functions below are kept for backward compatibility with
// astro/src/pages/api/products/*.js (sync.js, bulk-sync.js, [id].js) —
// those routes are redundant now that products come from Firestore at
// build time (see fetch-products.mjs's header comment), but haven't been
// removed yet. Mutations here never persist past this build, same as
// before this script existed — not a new limitation.
/** @type {import('./products.js').Product[]} */
export let syncedProducts = [];

export function addProduct(product) {
  syncedProducts.push(product);
  return product;
}

export function updateProduct(productId, updatedProduct) {
  const index = syncedProducts.findIndex((p) => p.id === productId);
  if (index >= 0) {
    syncedProducts[index] = { ...syncedProducts[index], ...updatedProduct };
    return syncedProducts[index];
  }
  return null;
}

export function deleteProduct(productId) {
  const index = syncedProducts.findIndex((p) => p.id === productId);
  if (index >= 0) {
    const deletedProduct = syncedProducts[index];
    syncedProducts.splice(index, 1);
    return deletedProduct;
  }
  return null;
}

export function getProduct(productId) {
  return syncedProducts.find((p) => p.id === productId);
}

export function getAllProducts() {
  return [...syncedProducts];
}

export function getProductByHandle(handle) {
  return syncedProducts.find((p) => p.handle === handle);
}

export function getInStockProducts() {
  return syncedProducts.filter((p) => p.inStock);
}
